    private const string TypePattern =
        "(Integer|Decimal|String|Boolean|Datetime|Date|Time|Uuid)";

    // The token after an operator's name: `round` with or without digits, the family
    // its operand declares (`YearDateIntegerRow` reads a date), then its declared type.
    [GeneratedRegex(
        "^(?<presence>With(out)?[A-Z][a-z]+)?"
            + "(?<family>"
            + TypePattern
            + "(?="
            + TypePattern
            + "))?(?<type>"
            + TypePattern
            + "(Nullable)?)$"
    )]
    private static partial Regex OperatorToken();

    // `DecimalNullable` → `decimal?`
    private static string TypeOfToken(string token)
    {
        string name = token.Replace("Nullable", "", StringComparison.Ordinal);
        string type = char.ToLowerInvariant(name[0]) + name[1..];
        Assert.Contains(type, TypeNames);
        return type + (token.EndsWith("Nullable", StringComparison.Ordinal) ? "?" : "");
    }

    private static (string Op, string Token) OperatorName(Type node)
    {
        string context = Assert.Single(
            Contexts,
            c => node.Name.EndsWith(c, StringComparison.Ordinal)
        );
        string name = node.Name[..^context.Length];
        string op = Operators
            .Where(o =>
                name.StartsWith(
                    char.ToUpperInvariant(o[0]) + o[1..],
                    StringComparison.Ordinal
                )
            )
            .MaxBy(o => o.Length)!;
        Assert.NotNull(op);
        return (op, name[op.Length..]);
    }

    [Fact]
    public void OperatorsDeclareTheTypeInTheirName()
    {
        Type[] operators = [.. Records.Where(typeof(IOperator).IsAssignableFrom)];
        Assert.NotEmpty(operators);
        foreach (Type node in operators)
        {
            (string op, string token) = OperatorName(node);
            string expected;
            if (token.Length == 0)
            {
                expected = op.StartsWith("tryAs", StringComparison.Ordinal)
                    ? char.ToLowerInvariant(op[5]) + op[6..] + "?"
                    : FixedTypes[op];
            }
            else if (Predicates.Contains(op))
            {
                // `EqualDecimalRow` compares decimals.
                _ = TypeOfToken(token);
                expected = "boolean";
            }
            else
            {
                Match match = OperatorToken().Match(token);
                Assert.True(match.Success, $"{node.Name} has no type in its name");
                expected = TypeOfToken(match.Groups["type"].Value);
            }
            Assert.True(
                expected == Declared(node),
                $"{node.Name} declares {Declared(node)}, not {expected}"
            );
        }
    }

    // The declared types of the expressions a union holds.
    private static string[] DeclaredCases(Type union)
    {
        return [.. Cases(union).Select(Declared).Distinct()];
    }

    [Fact]
    public void OperandsOfAFamilyDeclareIt()
    {
        // `YearDateIntegerRow` reads a date, `AsStringDecimalStringRow` a number.
        int families = 0;
        foreach (Type node in Records.Where(typeof(IOperator).IsAssignableFrom))
        {
            (string op, string token) = OperatorName(node);
            Match match = OperatorToken().Match(token);
            if (Predicates.Contains(op) || !match.Groups["family"].Success)
            {
                continue;
            }
            families++;
            string family = TypeOfToken(match.Groups["family"].Value);
            string[] accepted = family == "decimal" ? [family, "integer"] : [family];
            Type operand = node.GetProperty("Operand")!.PropertyType;
            Assert.All(
                DeclaredCases(operand),
                d => Assert.Contains(d.TrimEnd('?'), accepted)
            );
        }
        Assert.True(families > 0);
    }

    [Fact]
    public void RoundingToAWholeNumberTakesADecimal()
    {
        // Without digits, `round` and `truncate` read a decimal; with them, the
        // operand's type is kept.
        foreach (Type node in Records.Where(typeof(IOperator).IsAssignableFrom))
        {
            (string op, string token) = OperatorName(node);
            if (op is not ("round" or "truncate" or "floor" or "ceiling"))
            {
                continue;
            }
            string[] operand = DeclaredCases(node.GetProperty("Operand")!.PropertyType);
            bool withDigits = node.GetProperty("Digits") is not null;
            Assert.Equal(
                token.StartsWith("WithDigits", StringComparison.Ordinal)
                    || (
                        withDigits
                        && token.StartsWith("Decimal", StringComparison.Ordinal)
                    ),
                withDigits
            );
            string expected = !withDigits ? "decimal"
                : token.StartsWith("Decimal", StringComparison.Ordinal) ? "decimal"
                : "integer";
            Assert.All(operand, d => Assert.Equal(expected, d.TrimEnd('?')));
        }
    }

    [Fact]
    public void RangeWindowsSortByTheTypeOfTheirDistances()
    {
        Type[] windows =
        [
            .. Records.Where(r =>
                r.Name.StartsWith("WindowWithoutFrameWithRange", StringComparison.Ordinal)
            ),
        ];
        Assert.Equal(4, windows.Length);
        foreach (Type window in windows)
        {
            string type = window.Name["WindowWithoutFrameWithRange".Length..];
            Assert.Equal("Range" + type, window.GetProperty("Range")!.PropertyType.Name);
            Type item = window
                .GetProperty("OrderBy")!
                .PropertyType.GetGenericArguments()
                .Single();
            Assert.Equal("OrderItem" + type + "Row", item.Name);
            string name = char.ToLowerInvariant(type[0]) + type[1..];
            Assert.Equal(
                new[] { name, name + "?" }.Order(),
                DeclaredCases(item.GetProperty("Expression")!.PropertyType).Order()
            );
        }
    }

    [GeneratedRegex(
        "^(Integer|Decimal|String|Boolean|Date|Time|Datetime|Uuid)(Nullable)?"
            + "(Row|Projection|Group|Total)$"
    )]
    private static partial Regex Position();

    // The declared types each kind of expression union accepts.
    private static string[]? Accepted(Type union)
    {
        Match position = Position().Match(union.Name);
        if (position.Success)
        {
            string name = position.Groups[1].Value.ToLowerInvariant();
            bool nullable = position.Groups[2].Success;
            // A position takes its type, its nullable type if it is nullable, and an
            // integer where it takes a decimal.
            string[] names = name == "decimal" ? [name, "integer"] : [name];
            return [.. names.SelectMany(n => nullable ? new[] { n, n + "?" } : [n])];
        }
        string? context = Contexts.FirstOrDefault(c =>
            union.Name.EndsWith(c, StringComparison.Ordinal)
        );
        if (context is null || union.Namespace == typeof(PureQLQuery).Namespace)
        {
            return null;
        }
        string rest = union.Name[..^context.Length];
        if (rest == "Expr")
        {
            return [.. TypeNames.SelectMany(n => new[] { n, n + "?" })];
        }
        // `DeclaresDecimalRow`: exactly decimal; `IntegerNullableOrDecimalNullableRow`.
        string tokens = rest.StartsWith("Declares", StringComparison.Ordinal)
            ? rest["Declares".Length..]
            : rest;
        return [.. tokens.Split("Or").Select(TypeOfToken)];
    }

    [Fact]
    public void ExpressionUnionsHoldEveryExpressionTheyAccept()
    {
        Assert.Equal(4 * 16, Unions.Count(u => Position().IsMatch(u.Name)));
        Type[] unions = [.. Unions.Where(u => Accepted(u) is not null)];
        foreach (Type union in unions)
        {
            string context = Contexts.Single(c =>
                union.Name.EndsWith(c, StringComparison.Ordinal)
            );
            Type expressions = Unions.Single(u => u.Name == "Expr" + context);
            string[] accepted = Accepted(union)!;
            Assert.Equal(
                Cases(expressions)
                    .Where(e => accepted.Contains(Declared(e)))
                    .Select(e => e.Name)
                    .Order(StringComparer.Ordinal),
                Cases(union).Select(e => e.Name).Order(StringComparer.Ordinal)
            );
        }
        // Each context's expressions declare every type of the schema.
        foreach (string context in Contexts)
        {
            Type expressions = Unions.Single(u => u.Name == "Expr" + context);
            Assert.Equal(
                TypeNames.SelectMany(n => new[] { n, n + "?" }).Order(),
                Cases(expressions).Select(Declared).Distinct().Order()
            );
        }
    }

    [Fact]
    public void SubqueryColumnsDeclareTheirNullability()
    {
        Type[] columns = [.. Records.Where(typeof(ISubqueryColumn).IsAssignableFrom)];
        Assert.Equal(16, columns.Length);
        foreach (Type column in columns)
        {
            ISubqueryColumn instance = (ISubqueryColumn)
                Activator.CreateInstance(column, "totals", "total")!;
            Assert.Equal("totals", instance.Subquery);
            Assert.Equal("total", instance.Field);
            Assert.Equal(
                column.Name.EndsWith("Nullable", StringComparison.Ordinal),
                instance.Type.Nullable
            );
            Assert.Equal("ListSubqueryColumn" + TypeToken(instance.Type), column.Name);
        }
    }

    private static string TypeToken(IType type)
    {
        return char.ToUpperInvariant(type.Name[0])
            + type.Name[1..]
            + (type.Nullable ? "Nullable" : "");
    }
